from pathlib import Path
from html import escape
root=Path(__file__).resolve().parents[1]
landing=(root/'index.html').read_text()
header=landing[landing.index('<header class="header"'):landing.index('</header>')+len('</header>')]
footer=landing[landing.rfind('<footer>'):landing.rfind('</footer>')+len('</footer>')]
gh='https://github.com/erythrofr/ClothCraft'

def link(href,label,style='btn-blue'):
 return f'<a class="btn {style}" href="{href}"'+(' target="_blank" rel="noopener noreferrer"' if href.startswith('https:') else '')+f'>{label} <span>↗</span></a>'
def hero(kicker,title,lead,tags='',actions=''):
 return f'<section class="page-hero"><div class="page-breadcrumb"><a href="/">CLOTHCRAFT</a><span>/</span>{kicker.upper()}</div><h1>{title}</h1><p class="page-lead">{lead}</p><div class="hero-actions" style="justify-content:flex-start">{actions}</div><div class="hero-tags">'+''.join(f'<span>{t.strip()}</span>' for t in tags.split('|') if t.strip())+'</div></section>'
def section(head,children='',extra=''):
 return f'<section class="page-section {extra}"><div class="panel-heading">{head}</div>{children}</section>'
def cards(*items):
 out=['<div class="page-card-grid">']
 for i,(title,desc,href) in enumerate(items):
  x=f'<article class="page-card"><span class="num">{i+1:02}</span><h3>{title}</h3><p>{desc}</p>'
  if href:x+=f'<a class="link" href="{href}">Explore <span>↗</span></a>'
  out.append(x+'</article>')
 out.append('</div>')
 return ''.join(out)
def screenshot(name,alt):return f'<div class="page-screenshot"><img loading="lazy" src="../assets/{name}" alt="{escape(alt)}"></div>'
def highlight(title,text,cta='Explore the source',href=gh):return f'<div class="page-highlight"><div><span class="eyetag">KEEP BUILDING</span><h2>{title}</h2><p>{text}</p></div>{link(href,cta)}</div>'
def wrap(slug,title,desc,body,script=''):
 active=header.replace(f'href="/{slug}/"',f'href="/{slug}/" aria-current="page"')
 text=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#08090d"><meta name="description" content="{escape(desc,quote=True)}"><meta property="og:type" content="website"><meta property="og:title" content="{escape(title,quote=True)} — ClothCraft"><meta property="og:description" content="{escape(desc,quote=True)}"><link rel="icon" type="image/svg+xml" href="../favicon.svg"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Manrope:wght@400;500;600;700;800&display=swap" rel="stylesheet"><link rel="stylesheet" href="../style.css"><link rel="stylesheet" href="../site-pages.css"><title>{escape(title)} — ClothCraft</title></head><body><a class="skip-link" href="#main">Skip to content</a>{active}<main class="page-main" id="main">{body}</main>{footer.replace('href="#top"','href="/"')}<script src="../site-nav.js"></script>{f'<script src="../{script}"></script>' if script else ''}</body></html>'''
 p=root/slug;p.mkdir(exist_ok=True);(p/'index.html').write_text(text)
 print(f'{slug}/index.html',len(text))

